/* ------------------------------------------------------------------ */

static unsigned int rd16(const unsigned char *p)
{
    return p[0] | (p[1] << 8);
}

static unsigned long rd32(const unsigned char *p)
{
    return (unsigned long)p[0] | ((unsigned long)p[1] << 8) |
           ((unsigned long)p[2] << 16) | ((unsigned long)p[3] << 24);
}

static void unzip_first_member(ZFile *zf)
{
    const unsigned char *d = zf->data;
    size_t n = zf->len;
    unsigned int method, namelen, extralen;
    unsigned long csize;
    size_t start;
    unsigned char *out = NULL;
    size_t outlen = 0;

    if (n < 30) return;
    method = rd16(d + 8);
    csize = rd32(d + 18);
    namelen = rd16(d + 26);
    extralen = rd16(d + 28);
    start = 30 + (size_t)namelen + extralen;
    if (start > n) {
        start = n;
    }
    if (method == 0) {
        size_t avail = n - start;
        if (csize < avail) avail = csize;
        out = malloc(avail + 1);
        if (!out) return;
        memcpy(out, d + start, avail);
        outlen = avail;
    } else if (method == 8) {
        out = raw_inflate(d + start, n - start, &outlen);
    } else {
        out = NULL;
        outlen = 0;
    }
    free(zf->data);
    zf->data = out;
    zf->len = outlen;
}

ZFile *zf_open(const char *path)
{
    FILE *fp;
    ZFile *zf;
    size_t cap = 65536, len = 0, got;
    unsigned char *buf;

    fp = fopen(path, "rb");
    if (!fp) return NULL;
    buf = malloc(cap);
    if (!buf) { fclose(fp); return NULL; }
    for (;;) {
        if (len == cap) {
            unsigned char *nb = realloc(buf, cap * 2);
            if (!nb) break;
            buf = nb;
            cap *= 2;
        }
        got = fread(buf + len, 1, cap - len, fp);
        if (got == 0) break;
        len += got;
    }
    fclose(fp);
    zf = malloc(sizeof(*zf));
    if (!zf) { free(buf); return NULL; }
    zf->data = buf;
    zf->len = len;
    zf->pos = 0;
    zf->pushback = -2;
    if (len >= 4 && buf[0] == 'P' && buf[1] == 'K' && buf[2] == 3 && buf[3] == 4)
        unzip_first_member(zf);
    return zf;
}

void zf_close(ZFile *zf)
{
    if (!zf) return;
    free(zf->data);
    free(zf);
}

int zf_getc(ZFile *zf)
{
    if (zf->pushback != -2) {
        int c = zf->pushback;
        zf->pushback = -2;
        return c;
    }
    if (zf->pos >= zf->len) return EOF;
    return zf->data[zf->pos++];
}

void zf_ungetc(int c, ZFile *zf)
{
    if (c == EOF) {
        /* The reference implementation dies when pushing back EOF. */
        fflush(stdout);
        signal(SIGSEGV, SIG_DFL);
        raise(SIGSEGV);
        abort();
    }
    zf->pushback = c & 0xff;
}

char *zf_gets(char *buf, int size, ZFile *zf)
{
    int i = 0, c = 0;
    if (size <= 0) return NULL;
    while (i < size - 1) {
        c = zf_getc(zf);
        if (c == EOF) break;
        buf[i++] = (char)c;
        if (c == '\n') break;
    }
    buf[i] = '\0';
    if (i == 0 && c == EOF) return NULL;
    return buf;
}
