/*
 * UTF-8 helpers.  The decoder works on a fixed-size block, the way the
 * glyph reader needs it: it keeps decoding (also past NUL bytes) until
 * the block ends or an invalid sequence shows up; on error it stops,
 * leaving whatever was already stored in the output buffer.
 */
#include <stddef.h>
#include "common.h"

static int bad_lead_byte(unsigned char b)
{
    return b == 0xc0 || b == 0xc1 || b == 0xf5 || b == 0xff;
}

size_t utf8_decode_block(const unsigned char *in, size_t insize,
                         outchr *out, size_t outsize)
{
    const unsigned char *p = in, *end = in + insize;
    outchr *w = out, *wend = out + outsize;
    size_t count = 0, n, i;

    while (p < end) {
        outchr lead;
        int shift;

        if (bad_lead_byte(*p)) return 0;
        if ((*p & 0x80) == 0) { n = 1; lead = *p; }
        else if ((*p & 0xe0) == 0xc0) { n = 2; lead = *p & 0x1f; }
        else if ((*p & 0xf0) == 0xe0) { n = 3; lead = *p & 0x0f; }
        else if ((*p & 0xf8) == 0xf0) { n = 4; lead = *p & 0x07; }
        else if ((*p & 0xfc) == 0xf8) { n = 5; lead = *p & 0x03; }
        else if ((*p & 0xfe) == 0xfc) { n = 6; lead = *p & 0x01; }
        else return 0;

        if ((size_t)(end - p) < n) return 0;
        for (i = 1; i < n; i++)
            if ((p[i] & 0xc0) != 0x80) return 0;

        count++;
        if (w >= wend) return 0;
        *w = 0;
        shift = 0;
        for (i = 1; i < n; i++) {
            *w |= (outchr)(p[n - i] & 0x3f) << shift;
            shift += 6;
        }
        *w |= lead << shift;
        if (*w >= 0xd800 && *w <= 0xdfff) return 0;   /* surrogate */
        w++;
        p += n;
    }
    return count;
}

size_t utf8_encode_one(outchr wc, char *out, size_t outsize)
{
    unsigned long v;
    size_t n, i;
    unsigned char *p = (unsigned char *)out;

    if (wc >= 0xd800 && wc <= 0xdfff) return 0;
    if (wc < 0) return 0;
    v = (unsigned long)wc;
    if (v <= 0x7f) n = 1;
    else if (v <= 0x7ff) n = 2;
    else if (v <= 0xffff) n = 3;
    else if (v <= 0x1fffff) n = 4;
    else if (v <= 0x3ffffff) n = 5;
    else n = 6;
    if (outsize < n) return 0;
    if (n == 1) {
        p[0] = (unsigned char)v;
        return 1;
    }
    for (i = n - 1; i > 0; i--) {
        p[i] = (unsigned char)(0x80 | (v & 0x3f));
        v >>= 6;
    }
    switch (n) {
    case 2: p[0] = (unsigned char)(0xc0 | v); break;
    case 3: p[0] = (unsigned char)(0xe0 | v); break;
    case 4: p[0] = (unsigned char)(0xf0 | v); break;
    case 5: p[0] = (unsigned char)(0xf8 | v); break;
    default: p[0] = (unsigned char)(0xfc | (v & 1)); break;
    }
    return n;
}

size_t wlen(const outchr *s)
{
    size_t n = 0;
    while (s[n]) n++;
    return n;
}

void wcopy(outchr *dst, const outchr *src)
{
    while ((*dst++ = *src++) != 0)
        ;
}

void wappend(outchr *dst, const outchr *src)
{
    wcopy(dst + wlen(dst), src);
}
