static int font_maxlen;

typedef struct {
    inchr code;
    outchr **rows;
} Glyph;

static Glyph *glyphs;
static size_t nglyphs, capglyphs;

/* hash index: code -> most recent glyph index */
static long *hindex;
static size_t hsize;

static size_t hash_code(inchr c)
{
    unsigned long x = (unsigned long)c;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdUL;
    x ^= x >> 33;
    return (size_t)x;
