static void index_insert(size_t gi)
{
    size_t h = hash_code(glyphs[gi].code) & (hsize - 1);
    while (hindex[h] >= 0) {
        if (glyphs[hindex[h]].code == glyphs[gi].code) break;
        h = (h + 1) & (hsize - 1);
    }
    hindex[h] = (long)gi;
}

static void index_rebuild(void)
{
    size_t i;
    free(hindex);
    hindex = xmalloc(sizeof(long) * hsize);
    for (i = 0; i < hsize; i++) hindex[i] = -1;
    for (i = 0; i < nglyphs; i++) index_insert(i);
