 * when it could not be opened).
 */
int open_font_file(const char *name, const char *suffix, ZFile **out)
{
    struct stat st;
    size_t need = strlen(g_fontdir) + strlen(name) + strlen(suffix) + 2;
    char *path = xmalloc(need);

    *out = NULL;
    if (!strchr(name, '/')) {
        strcpy(path, g_fontdir);
