/* Buffers that persist between glyph reads, like stack slots reused by
   consecutive calls in the reference implementation. */
static char *rawline;
static outchr decoded[MAXLEN + 1];

static void read_glyph(ZFile *zf, inchr code)
{
    Glyph *g = new_glyph(code);
    int row;

    decoded[0] = 0;
    for (row = 0; row < g_charheight; row++) {
        int k;
        outchr mark;
        if (!read_limited_line(zf, rawline, MAXLEN))
            rawline[0] = '\0';
        utf8_decode_block((const unsigned char *)rawline, MAXLEN, decoded, MAXLEN);
        decoded[MAXLEN] = 0;
        k = (int)wlen(decoded) - 1;
        while (k >= 0 && decoded[k] >= 0 && decoded[k] < 128 && isspace(decoded[k]))
            k--;
        if (k >= 0) {
            mark = decoded[k];
            while (k >= 0 && decoded[k] == mark) k--;
        }
        decoded[k + 1] = 0;
        g->rows[row] = xcalloc_bytes(sizeof(outchr) * (wlen(decoded) + 1 + MAXLEN + 2));
        wcopy(g->rows[row], decoded);
    }
    register_glyph();
}

void load_font(void)
{
    static const inchr extra_latin[7] = {196, 214, 220, 228, 246, 252, 223};
    ZFile *zf = NULL;
    char magic[5];
    char *header;
    char hb = 0;
    int height = 0, maxlen = 0, oldlayout = 0, comments = 0, fontdir = 0, layout = 0;
    int nread, i, row;
    inchr code;
    char *codeline;

    g_toilet = 0;
    open_font_file(g_fontname, ".flf", &zf);
    if (zf == NULL) {
        open_font_file(g_fontname, ".tlf", &zf);
        if (zf) g_toilet = 1;
    }
    if (zf == NULL) {
        fprintf(stderr, "%s: %s: Unable to open font file\n", g_progname, g_fontname);
        exit(1);
    }

    for (i = 0; i < 4; i++) magic[i] = (char)zf_getc(zf);
    magic[4] = '\0';

    header = xmalloc(MAXFIRSTLINELEN + 2);
    if (!read_limited_line(zf, header, MAXFIRSTLINELEN + 1) && header[0] == '\0')
        header[0] = '\0';
    {
        size_t hl = strlen(header);
        if (hl > 0 && header[hl - 1] != '\n') skip_rest_of_line(zf);
    }
    nread = sscanf(header, "%*c%c %d %*d %d %d %d%*[ \t]%d%*[ \t]%d",
                   &hb, &height, &maxlen, &oldlayout, &comments, &fontdir, &layout);
    free(header);

    if ((!g_toilet && strcmp(magic, "flf2") != 0) ||
        (g_toilet && strcmp(magic, "tlf2") != 0) || nread < 5) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 font file\n", g_progname, g_fontname);
        exit(1);
    }
    g_hardblank = hb;

    for (i = 1; i <= comments; i++) skip_rest_of_line(zf);

    if (nread < 6) fontdir = 0;
    if (nread < 7) {
        if (oldlayout == 0) layout = SM_KERN;
        else if (oldlayout < 0) layout = 0;
        else layout = (oldlayout & 31) | SM_SMUSH;
    }
    if (height < 1) height = 1;
    if (maxlen < 1) maxlen = 1;
    maxlen += 100;
    font_maxlen = maxlen;
    g_charheight = height;

    if (g_smushoverride == SMO_NO) g_smushmode = layout;
    else if (g_smushoverride == SMO_FORCE) g_smushmode |= layout;

    if (g_rtl < 0) g_rtl = fontdir;
    if (g_justify < 0) g_justify = 2 * g_rtl;

    {
        size_t rl = (size_t)(maxlen > MAXLEN ? maxlen : MAXLEN) + 8;
        rawline = xcalloc_bytes(rl);
    }

    /* the "missing character" glyph */
    {
        Glyph *g = new_glyph(0);
        for (row = 0; row < g_charheight; row++)
            g->rows[row] = xcalloc_bytes(sizeof(outchr) * (MAXLEN + 2));
        register_glyph();
    }

    for (code = ' '; code <= '~'; code++) read_glyph(zf, code);
    for (i = 0; i < 7; i++) read_glyph(zf, extra_latin[i]);

    codeline = xmalloc((size_t)maxlen + 8);
    for (;;) {
        long v;
        if (!read_limited_line(zf, codeline, maxlen + 1)) break;
        if (sscanf(codeline, "%li", &v) != 1) break;
        read_glyph(zf, (inchr)v);
    }
    free(codeline);
    zf_close(zf);
}
EOF"}

