/*
 * Control files (character mappings and input encodings) and the input
 * character reader.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "common.h"

/* ---------------- control file list ---------------- */

static char **cf_names;
static size_t cf_count, cf_cap;

void add_control_file(char *name)
{
    if (cf_count == cf_cap) {
        cf_cap = cf_cap ? cf_cap * 2 : 8;
        cf_names = realloc(cf_names, sizeof(char *) * cf_cap);
        if (!cf_names) {
            fprintf(stderr, "%s: Out of memory\n", g_progname);
            exit(1);
        }
    }
    cf_names[cf_count++] = name;
}

void clear_control_files(void)
{
    cf_count = 0;
}

/* ---------------- mapping commands ---------------- */

typedef struct {
    int translate;      /* 1 = translation range, 0 = freeze marker */
    inchr lo, hi, delta;
} MapCmd;

static MapCmd *cmds;
static size_t ncmds, capcmds;

static void push_cmd(int translate, inchr lo, inchr hi, inchr delta)
{
    if (ncmds == capcmds) {
        capcmds = capcmds ? capcmds * 2 : 64;
        cmds = realloc(cmds, sizeof(MapCmd) * capcmds);
        if (!cmds) {
            fprintf(stderr, "%s: Out of memory\n", g_progname);
            exit(1);
        }
    }
    cmds[ncmds].translate = translate;
    cmds[ncmds].lo = lo;
    cmds[ncmds].hi = hi;
    cmds[ncmds].delta = delta;
    ncmds++;
}

inchr apply_mappings(inchr c)
{
    size_t i = 0;
    while (i < ncmds) {
        if (cmds[i].translate && c >= cmds[i].lo && c <= cmds[i].hi) {
            c += cmds[i].delta;
            /* skip ahead to the next freeze marker */
            while (i < ncmds && cmds[i].translate) i++;
        } else {
            i++;
        }
    }
    return c;
}

/* ---------------- input encoding state ---------------- */

static int encoding;            /* 0 iso2022, 1 dbcs, 2 utf8, 3 hz, 4 sjis */
static long gset[4];
static int gdouble[4];
static int gleft, gright;
static int hz_active;

void reset_charsets(void)
{
    encoding = 0;
    gset[0] = 0;
    gset[1] = 0x80;
    gset[2] = gset[3] = 0;
    gdouble[0] = gdouble[1] = gdouble[2] = gdouble[3] = 0;
    gleft = 0;
    gright = 1;
}

/* ---------------- control file parsing ---------------- */

static void cf_skipws(ZFile *zf)
{
    int c;
    while (c = zf_getc(zf), c != EOF && isascii(c) && isspace(c))
        ;
    zf_ungetc(c, zf);
}

static void cf_skipline(ZFile *zf)
{
    int c;
    while ((c = zf_getc(zf)) != EOF)
        if (c == '\n') return;
}

static void cf_number(ZFile *zf, inchr *result)
{
    static const char digits[] = "0123456789ABCDEF";
    unsigned int acc = 0;
    int sign = 1, base, c;
    const char *pos;

    cf_skipws(zf);
    c = zf_getc(zf);
    if (c == '-') sign = -1;
    else zf_ungetc(c, zf);
    c = zf_getc(zf);
    if (c == '0') {
        c = zf_getc(zf);
        if (c == 'x' || c == 'X') {
            base = 16;
        } else {
            base = 8;
            zf_ungetc(c, zf);
        }
    } else {
        base = 10;
        zf_ungetc(c, zf);
    }
    while ((c = zf_getc(zf)) != EOF) {
        c = toupper(c);
        pos = strchr(digits, c);
        if (pos == NULL || pos - digits >= base) {
            zf_ungetc(c, zf);
            break;
        }
        acc = acc * (unsigned int)base + (unsigned int)(pos - digits);
    }
    *result = (inchr)((int)acc * sign);
}

static inchr cf_char(ZFile *zf)
{
    inchr ch;
    signed char esc;

    ch = zf_getc(zf);
    if (ch == '\n' || ch == '\r') {
        zf_ungetc((int)ch, zf);
        return 0;
    }
    if (ch != '\\') return ch;
    esc = (signed char)zf_getc(zf);
    switch (esc) {
    case 'a': return 7;
    case 'b': return 8;
    case 'e': return 27;
    case 'f': return 12;
    case 'n': return 10;
    case 'r': return 13;
    case 't': return 9;
    case 'v': return 11;
    default:
        if (esc == '-' || esc == 'x' || (esc >= '0' && esc <= '9')) {
            zf_ungetc(esc, zf);
            cf_number(zf, &ch);
            return ch;
        }
        return esc;
    }
}

static void cf_charset(int n, ZFile *zf)
{
    int c;

    cf_skipws(zf);
    if (zf_getc(zf) != '9') {
        cf_skipline(zf);
        return;
    }
    c = zf_getc(zf);
    if (c == '6') {
        gset[n] = 65536L * zf_getc(zf) + 0x80;
        gdouble[n] = 0;
        cf_skipline(zf);
        return;
    }
    if (c != '4') {
        cf_skipline(zf);
        return;
    }
    c = zf_getc(zf);
    if (c == 'x') {
        if (zf_getc(zf) != '9') {
            cf_skipline(zf);
            return;
        }
        if (zf_getc(zf) != '4') {
            cf_skipline(zf);
            return;
        }
        cf_skipws(zf);
        gset[n] = 65536L * zf_getc(zf);
        gdouble[n] = 1;
        cf_skipline(zf);
        return;
    }
    zf_ungetc(c, zf);
    cf_skipws(zf);
    gset[n] = 65536L * zf_getc(zf);
    gdouble[n] = 0;
}

static void read_control_file(const char *name)
{
    ZFile *zf = NULL;
    int c;

    open_font_file(name, ".flc", &zf);
    if (zf == NULL) {
        fprintf(stderr, "%s: %s: Unable to open control file\n", g_progname, name);
        exit(1);
    }
    while ((c = zf_getc(zf)) != EOF) {
        switch (c) {
        case 't': {
            inchr first, last, target;
            int dash;
            cf_skipws(zf);
            first = cf_char(zf);
            dash = (signed char)zf_getc(zf);
            if (dash == '-') {
                last = cf_char(zf);
            } else {
                zf_ungetc(dash, zf);
                last = first;
            }
            cf_skipws(zf);
            target = cf_char(zf);
            cf_skipline(zf);
            push_cmd(1, first, last, target - first);
            break;
        }
        case '0': case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8': case '9':
        case '-': {
            inchr from, to;
            zf_ungetc(c, zf);
            cf_number(zf, &from);
            cf_skipws(zf);
            cf_number(zf, &to);
            cf_skipline(zf);
            push_cmd(1, from, from, to - from);
            break;
        }
        case 'f':
            cf_skipline(zf);
            push_cmd(0, 0, 0, 0);
            break;
        case 'b':
            encoding = 1;
            break;
        case 'u':
            encoding = 2;
            break;
        case 'h':
            encoding = 3;
            break;
        case 'j':
            encoding = 4;
            break;
        case 'g':
            encoding = 0;
            cf_skipws(zf);
            c = zf_getc(zf);
            switch (c) {
            case '0': cf_charset(0, zf); break;
            case '1': cf_charset(1, zf); break;
            case '2': cf_charset(2, zf); break;
            case '3': cf_charset(3, zf); break;
            case 'l': case 'L':
                cf_skipws(zf);
                gleft = zf_getc(zf) - '0';
                cf_skipline(zf);
                break;
            case 'r': case 'R':
                cf_skipws(zf);
                gright = zf_getc(zf) - '0';
                cf_skipline(zf);
                break;
            default:
                cf_skipline(zf);
                break;
            }
            break;
        case '\r':
        case '\n':
            break;
        default:
            cf_skipline(zf);
            break;
        }
    }
    zf_close(zf);
}

void load_control_files(void)
{
    size_t i;
    for (i = 0; i < cf_count; i++) read_control_file(cf_names[i]);
