/* ---------------- raw input (stdin or command line words) ---------------- */

static int src_args;
static char **src_argv;
static int src_argc;
static int src_word;
static int src_pos;            /* -1 once exhausted */

void input_setup(int argc, char **argv, int first_arg, int from_args)
{
    src_argc = argc;
    src_argv = argv;
    src_word = first_arg;
    src_pos = 0;
    src_args = from_args;
}

static int raw_getc(void)
{
    int c;

    if (!src_args) return getchar();
    if (src_pos < 0 || src_word >= src_argc) return EOF;
    c = (unsigned char)src_argv[src_word][src_pos++];
    if (c == 0) {
        /* end of a word: blank between words, newline for an empty word */
        c = (src_pos == 1) ? '\n' : ' ';
        src_pos = 0;
        if (++src_word >= src_argc) {
            c = EOF;
            src_pos = -1;
        }
    }
    return c;
}

/* ---------------- decoding ---------------- */

static inchr read_iso2022(void)
{
    inchr ch, ch2;
    int save_l, save_r;

    ch = raw_getc();
    if (ch == EOF) return ch;
    if (ch == 27) ch = raw_getc() + 0x100;
    if (ch == 0x100 + '$') ch = raw_getc() + 0x200;

    switch (ch) {
    case 14:
        gleft = 1;
        return read_iso2022();
    case 15:
        gleft = 0;
        return read_iso2022();
    case 142:
    case 0x100 + 'N':
        save_l = gleft; save_r = gright;
        gleft = gright = 2;
        ch = read_iso2022();
        gleft = save_l; gright = save_r;
        return ch;
    case 143:
    case 0x100 + 'O':
        save_l = gleft; save_r = gright;
        gleft = gright = 3;
        ch = read_iso2022();
        gleft = save_l; gright = save_r;
        return ch;
    case 0x100 + 'n':
        gleft = 2;
        return read_iso2022();
    case 0x100 + 'o':
        gleft = 3;
        return read_iso2022();
    case 0x100 + '~':
        gright = 1;
        return read_iso2022();
    case 0x100 + '}':
        gright = 2;
        return read_iso2022();
    case 0x100 + '|':
        gright = 3;
        return read_iso2022();
    case 0x100 + '(':
    case 0x100 + ')':
    case 0x100 + '*':
    case 0x100 + '+': {
        int n = (int)(ch - (0x100 + '('));
        ch = raw_getc();
        if (ch == 'B') ch = 0;
        gset[n] = ch << 16;
        gdouble[n] = 0;
        return read_iso2022();
    }
    case 0x100 + '-':
    case 0x100 + '.':
    case 0x100 + '/': {
        int n = (int)(ch - (0x100 + '-')) + 1;
        ch = raw_getc();
        if (ch == 'A') ch = 0;
        gset[n] = (ch << 16) | 0x80;
        gdouble[n] = 0;
        return read_iso2022();
    }
    case 0x200 + '(':
    case 0x200 + ')':
    case 0x200 + '*':
    case 0x200 + '+': {
        int n = (int)(ch - (0x200 + '('));
        ch = raw_getc();
        gset[n] = ch << 16;
        gdouble[n] = 1;
        return read_iso2022();
    }
    default:
        if (ch & 0x200) {
            gset[0] = (ch & ~0x200L) << 16;
            gdouble[0] = 1;
            return read_iso2022();
        }
        break;
    }

    if (ch >= 0x21 && ch <= 0x7e) {
        if (gdouble[gleft]) {
            ch2 = raw_getc();
            return gset[gleft] | (ch << 8) | ch2;
        }
        return gset[gleft] | ch;
    }
    if (ch >= 0xa0 && ch <= 0xff) {
        if (gdouble[gright]) {
            ch2 = raw_getc();
            return gset[gright] | (ch << 8) | ch2;
        }
        return gset[gright] | (ch & ~0x80L);
    }
    return ch;
}

static int have_pushed;
static inchr pushed;

void push_back_input_char(inchr c)
{
    pushed = c;
    have_pushed = 1;
}

inchr next_input_char(void)
{
    inchr ch, c2, c3, c4, c5, c6;

    if (have_pushed) {
        have_pushed = 0;
        return pushed;
    }

    switch (encoding) {
    case 0:
        return read_iso2022();
    case 1:
    case 4:
        if ((ch = raw_getc()) == EOF) return ch;
        if ((ch >= 0x80 && ch <= 0x9f) || (ch >= 0xe0 && ch <= 0xef))
            ch = (ch << 8) + raw_getc();
        return ch;
    case 2:
        if ((ch = raw_getc()) == EOF) return ch;
        if (ch < 0x80) return ch;
        if (ch < 0xc0) return 0x80;
        if (ch < 0xe0) {
            c2 = raw_getc();
            return ((ch & 0x1f) << 6) + (c2 & 0x3f);
        }
        if (ch < 0xf0) {
            c2 = raw_getc();
            c3 = raw_getc();
            return ((ch & 0x0f) << 12) + ((c2 & 0x3f) << 6) + (c3 & 0x3f);
        }
        if (ch < 0xf8) {
            c2 = raw_getc();
            c3 = raw_getc();
            c4 = raw_getc();
            return ((ch & 0x07) << 18) + ((c2 & 0x3f) << 12) +
                   ((c3 & 0x3f) << 6) + (c4 & 0x3f);
        }
        if (ch < 0xfc) {
            c2 = raw_getc();
            c3 = raw_getc();
            c4 = raw_getc();
            c5 = raw_getc();
            return ((ch & 0x03) << 24) + ((c2 & 0x3f) << 18) +
                   ((c3 & 0x3f) << 12) + ((c4 & 0x3f) << 6) + (c5 & 0x3f);
        }
        if (ch < 0xfe) {
            c2 = raw_getc();
            c3 = raw_getc();
            c4 = raw_getc();
            c5 = raw_getc();
            c6 = raw_getc();
            return ((ch & 0x01) << 30) + ((c2 & 0x3f) << 24) +
                   ((c3 & 0x3f) << 18) + ((c4 & 0x3f) << 12) +
                   ((c5 & 0x3f) << 6) + (c6 & 0x3f);
        }
        return 0x80;
    case 3:
        if ((ch = raw_getc()) == EOF) return ch;
        if (hz_active) {
            ch = (ch << 8) + raw_getc();
            if (ch == ('}' << 8) + '~') {
                hz_active = 0;
                return next_input_char();
            }
            return ch;
        }
        if (ch == '~') {
            ch = raw_getc();
            if (ch == '{') {
                hz_active = 1;
                return next_input_char();
            }
            if (ch == '~') return ch;
            return next_input_char();
        }
        return ch;
    default:
        return 0x80;
    }
}
