    cmds[ncmds].delta = delta;
    ncmds++;
}

inchr apply_mappings(inchr c)
{
    size_t i = 0;
    while (i < ncmds) {
        if (cmds[i].translate && c >= cmds[i].lo && c <= cmds[i].hi) {
            c += cmds[i].delta;
