static void cf_skipline(ZFile *zf)
{
    int c;
    while ((c = zf_getc(zf)) != EOF)
        if (c == '\n') return;
}

static void cf_number(ZFile *zf, inchr *result)
{
    static const char digits[] = "0123456789ABCDEF";
    unsigned int acc = 0;
    int sign = 1, base, c;
    const char *pos;

    cf_skipws(zf);
    c = zf_getc(zf);
    if (c == '-') sign = -1;
    else zf_ungetc(c, zf);
