#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "common.h"

static outchr **line;           /* the output line being built, per row */
static int linelen;             /* length of row 0 */
static inchr *chars;            /* input characters on the current line */
static int nchars;
static int charlimit;
static outchr *scratch;         /* temporary row for right-to-left joins */

static outchr **glyph;          /* current glyph */
static int glyphwidth;
static int prevwidth;

static size_t row_capacity;

/* emulate strchr(set, (char)c) != NULL, including the terminator match */
static int in_set(const char *set, outchr c)
{
    return strchr(set, (char)c) != NULL;
