static outchr smush_pair(outchr left, outchr right)
{
    int hb = g_hardblank;

    if (left == ' ') return right;
    if (right == ' ') return left;

    if (prevwidth < 2 || glyphwidth < 2) return 0;

    if ((g_smushmode & SM_SMUSH) == 0) return 0;

    if ((g_smushmode & 63) == 0) {
        /* universal overlapping */
