        if (right == ' ') return left;
        if (left == hb) return right;
        if (right == hb) return left;
        if (g_rtl == 1) return left;
        return right;
    }

    if (g_smushmode & SM_HARDBLANK) {
        if (left == hb && right == hb) return left;
    }

    if (left == hb || right == hb) return 0;

    if (g_smushmode & SM_EQUAL) {
        if (left == right) return left;
    }

    if (g_smushmode & SM_LOWLINE) {
        if (left == '_' && in_set("|/\\[]{}()<>", right)) return right;
        if (right == '_' && in_set("|/\\[]{}()<>", left)) return left;
    }

    if (g_smushmode & SM_HIERARCHY) {
        if (left == '|' && in_set("/\\[]{}()<>", right)) return right;
        if (right == '|' && in_set("/\\[]{}()<>", left)) return left;
        if (in_set("/\\", left) && in_set("[]{}()<>", right)) return right;
        if (in_set("/\\", right) && in_set("[]{}()<>", left)) return left;
        if (in_set("[]", left) && in_set("{}()<>", right)) return right;
        if (in_set("[]", right) && in_set("{}()<>", left)) return left;
        if (in_set("{}", left) && in_set("()<>", right)) return right;
        if (in_set("{}", right) && in_set("()<>", left)) return left;
        if (in_set("()", left) && in_set("<>", right)) return right;
        if (in_set("()", right) && in_set("<>", left)) return left;
    }

    if (g_smushmode & SM_PAIR) {
        if (left == '[' && right == ']') return '|';
        if (right == '[' && left == ']') return '|';
        if (left == '{' && right == '}') return '|';
        if (right == '{' && left == '}') return '|';
        if (left == '(' && right == ')') return '|';
        if (right == '(' && left == ')') return '|';
    }

    if (g_smushmode & SM_BIGX) {
        if (left == '/' && right == '\\') return '|';
        if (right == '/' && left == '\\') return 'Y';
        if (left == '>' && right == '<') return 'X';
    }

    return 0;
