        }
        free(probe);
        line[i] = xcalloc_bytes(sizeof(outchr) * row_capacity);
    }
    charlimit = g_outputwidth * 4 + 100;
    want = sizeof(inchr) * (size_t)(charlimit + 1);
    chars = malloc(want ? want : 1);
    if (!chars) {
        fprintf(stderr, "%s: Out of memory\n", g_progname);
        exit(1);
    }
    scratch = xcalloc_bytes(sizeof(outchr) * row_capacity);
