}

static void load_glyph(inchr c)
{
    glyph = find_glyph(c);
    prevwidth = glyphwidth;
    glyphwidth = (int)wlen(glyph[0]);
}

int layout_add(inchr c)
{
    int amount, row, k, col;

    load_glyph(c);
    amount = smush_distance();
    if (linelen + glyphwidth - amount > g_linelimit || nchars + 1 > charlimit)
        return 0;

    for (row = 0; row < g_charheight; row++) {
        if (g_rtl) {
            wcopy(scratch, glyph[row]);
            for (k = 0; k < amount; k++) {
                col = glyphwidth - amount + k;
                if (col < 0) col = 0;
                scratch[col] = smush_pair(scratch[col], line[row][k]);
            }
            wappend(scratch, line[row] + amount);
            wcopy(line[row], scratch);
        } else {
            for (k = 0; k < amount; k++) {
                col = linelen - amount + k;
                if (col < 0) col = 0;
                line[row][col] = smush_pair(line[row][col], glyph[row][k]);
            }
            wappend(line[row], glyph[row] + amount);
        }
    }
    linelen = (int)wlen(line[0]);
    chars[nchars++] = c;
    return 1;
}

int layout_width(void)
{
    return linelen;
}

void emit_row(const outchr *row)
{
    int i, len;
    char buf[10];

    len = (int)wlen(row);
    if (g_outputwidth > 1) {
        if (len > g_outputwidth - 1) len = g_outputwidth - 1;
        if (g_justify > 0) {
            for (i = 1; (3 - g_justify) * i + len + g_justify - 2 < g_outputwidth; i++)
                putchar(' ');
        }
    }
    for (i = 0; i < len; i++) {
        size_t n = utf8_encode_one(row[i], buf, sizeof(buf));
        if (n == 1 && buf[0] == (char)g_hardblank) buf[0] = ' ';
        fwrite(buf, 1, n, stdout);
    }
    putchar('\n');
}

void layout_flush(void)
{
    int i;
    for (i = 0; i < g_charheight; i++) emit_row(line[i]);
