}

void layout_emit_lone_glyph(void)
{
    int i;
    for (i = 0; i < g_charheight; i++) {
        if (g_rtl && g_outputwidth > 1) {
            int off = (int)wlen(glyph[i]) - g_linelimit;
            if (off < 0) off = 0;
