   the next line. */
void layout_split(void)
{
    int i, gotspace = 0, lastspace, len1, len2;
    inchr *part1, *part2;

    part1 = xmalloc(sizeof(inchr) * (size_t)(nchars + 1));
    part2 = xmalloc(sizeof(inchr) * (size_t)(nchars + 1));
    lastspace = nchars - 1;
    for (i = nchars - 1; i >= 0; i--) {
        if (!gotspace && chars[i] == ' ') {
            gotspace = 1;
            lastspace = i;
        }
        if (gotspace && chars[i] != ' ') break;
    }
    len1 = i + 1;
    len2 = nchars - lastspace - 1;
    for (i = 0; i < len1; i++) part1[i] = chars[i];
    for (i = 0; i < len2; i++) part2[i] = chars[lastspace + 1 + i];
