    return "".join(parts)

def rand_opts(r):
    o = []
    if r.random() < 0.5:
        o += ["-d", "fonts", "-f", r.choice(fonts)]
    else:
        o += ["-d", "assets", "-f", r.choice(assets)]
    for _ in range(r.randint(0, 4)):
        k = r.random()
        if k < 0.15: o.append(r.choice(["-c", "-l", "-r", "-x"]))
        elif k < 0.35: o.append(r.choice(["-k", "-W", "-o", "-S", "-s"]))
        elif k < 0.45: o += ["-m", str(r.choice([-3,-2,-1,0,1,2,3,4,5,7,8,15,16,24,31,32,33,63,64,127,128,191]))]
        elif k < 0.55: o.append(r.choice(["-L", "-R", "-X"]))
        elif k < 0.7: o += ["-w", str(r.choice([1, 2, 3, 5, 10, 20, 30, 40, 60, 80, 100, 132, 200]))]
        elif k < 0.8: o.append(r.choice(["-p", "-n"]))
        elif k < 0.85: o.append(r.choice(["-D", "-E"]))
        elif k < 0.95: o += ["-C", "fonts/" + r.choice(ctrls)]
        else: o.append("-N")
    return o

def main(seed, count):
    r = random.Random(seed)
    bad = 0
    for i in range(count):
        opts = rand_opts(r)
        text = rand_text(r)
        if r.random() < 0.5:
            ok = compare(opts, text.encode('latin-1'))
        else:
            args = text.split(" ") if text else []
            ok = compare(opts + args, b"")
        if not ok:
            bad += 1
            if bad > 5: break
    print("done, bad =", bad)

